UPDATE APPROVAL_REQUEST SET STATUS = #{status}, CURRENT_STEP = #{currentStep},
       RESULT_NOTE = #{note,jdbcType=VARCHAR}, DECIDED_AT = #{decidedAt,jdbcType=VARCHAR}
 WHERE REQ_ID = #{id}

UPDATE APPROVAL_STEP SET STATUS = #{status}, ACTED_BY = #{actedBy,jdbcType=VARCHAR}, ACTED_AS_DEPUTY = #{deputy},
       COMMENT_TEXT = #{comment,jdbcType=VARCHAR}, ACTED_AT = #{at,jdbcType=VARCHAR}
 WHERE STEP_ID = #{stepId}
